1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.CityRegion;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * The upper-cased first letters of the first and last name, dot-separated with a
32	     * trailing dot, e.g. {@code J.S.}.
33	     */
34	    default String initials(Owner owner) {
35	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
36	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
37	    }
38	
39	    /**
40	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
41	     * {@code YY} is the last two digits of the registration date year, e.g.
42	     * {@code SMI-0007-M26}.
43	     */
44	    default String membershipNumber(Owner owner) {
45	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
46	        return owner.getCustomerCode() + "-M" + yy;
47	    }
48	
49	    /**
50	     * The owner's membership tier: {@code GOLD} when the owner's household (owners sharing
51	     * the same {@code householdId}) has 3 or more members; otherwise {@code SILVER} when the
52	     * owner has no namesakes ({@code namesakeCount} is 0) and an email address is present,
53	     * otherwise {@code BRONZE}.
54	     */
55	    default String membershipTier(Owner owner) {
56	        Integer householdMembers = owner.getHouseholdMemberCount();
57	        if (householdMembers != null && householdMembers >= 3) {
58	            return "GOLD";
59	        }
60	        boolean noNamesakes = Integer.valueOf(0).equals(owner.getNamesakeCount());
61	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
62	        return noNamesakes && hasEmail ? "SILVER" : "BRONZE";
63	    }
64	
65	    /**
66	     * The canonical region derived from the owner's city via the pinned city-to-region
67	     * table, or {@code UNKNOWN} when the city is not in the table.
68	     */
69	    default String locality(Owner owner) {
70	        return CityRegion.localityOf(owner.getCity());
71	    }
72	
73	    @Mapping(target = "householdMemberCount", ignore = true)
74	    Owner toOwner(OwnerDto ownerDto);
75	
76	    @Mapping(target = "id", ignore = true)
77	    @Mapping(target = "pets", ignore = true)
78	    @Mapping(target = "customerCode", ignore = true)
79	    @Mapping(target = "householdId", ignore = true)
80	    @Mapping(target = "namesakeCount", ignore = true)
81	    @Mapping(target = "householdMemberCount", ignore = true)
82	    Owner toOwner(OwnerFieldsDto ownerDto);
83	
84	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
85	
86	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
87	
88	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
89	        OwnerPageDto ownerPageDto = new OwnerPageDto();
90	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
91	        ownerPageDto.setPage(ownerPage.getNumber());
92	        ownerPageDto.setSize(ownerPage.getSize());
93	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
94	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
95	        return ownerPageDto;
96	    }
97	}
