1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Emits an audit record for a successfully created owner. Runs after {@link SaveOwner}
11	 * so the generated id is available, publishing the owner id, customer code and
12	 * registration date to the dedicated {@code AUDIT} logger.
13	 */
14	public class AuditOwnerCreated {
15	
16	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
17	
18	    public void service(@Val Owner owner) {
19	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
20	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
21	    }
22	}
