2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Namesake matching: an owner is a namesake of another when they share the same first and
7	 * last name, compared case-insensitively (and ignoring surrounding/internal whitespace).
8	 * Used to count how many existing owners already carry a new owner's name.
9	 */
10	final class Namesakes {
11	
12	    private Namesakes() {
13	    }
14	
15	    /**
16	     * Whether {@code owner} shares the given first and last name, comparing both in their
17	     * canonical (trimmed, whitespace-collapsed, lower-cased) forms.
18	     */
19	    static boolean matches(Owner owner, String firstName, String lastName) {
20	        return normalize(firstName).equals(normalize(owner.getFirstName()))
21	                && normalize(lastName).equals(normalize(owner.getLastName()));
22	    }
23	
24	    private static String normalize(String name) {
25	        if (name == null) {
26	            return "";
27	        }
28	        return name.trim().replaceAll("\\s+", " ").toLowerCase();
29	    }
30	}
