7	/**
8	 * Records how many owners share the new owner's household. Counts the existing owners with
9	 * the same {@code householdId} (assigned earlier by {@link AssignHousehold}) and adds one
10	 * for the owner being created, so the count reflects the household size that results from
11	 * this create. An owner not sharing a household ({@code householdId} is {@code null}) is a
12	 * household of one.
13	 */
14	public class CountHouseholdMembers {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        int count = 1;
18	        String householdId = owner.getHouseholdId();
19	        if (householdId != null) {
20	            for (Owner existing : ownerRepository.findAll()) {
21	                if (householdId.equals(existing.getHouseholdId())) {
22	                    count++;
23	                }
24	            }
25	        }
26	        owner.setHouseholdMemberCount(count);
27	    }
28	}
